using System;
using System.Collections.Generic;

namespace WristConductor.Core
{
    #region 枚举定义

    /// <summary>
    /// 手势动作类型
    /// </summary>
    public enum GestureType
    {
        None = 0,
        Tap = 1,
        SwipeUp = 2,
        SwipeDown = 3,
        SwipeLeft = 4,
        SwipeRight = 5,
        LongPress = 6,
        Flick = 7
    }

    /// <summary>
    /// 命中结果
    /// </summary>
    public enum HitResult
    {
        Miss = 0,
        Good = 1,
        Perfect = 2
    }

    /// <summary>
    /// 评级
    /// </summary>
    public enum Rating
    {
        None = 0,
        D = 1,
        C = 2,
        B = 3,
        A = 4,
